def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

sum_of_primes = 0
for i in range(10000):
    if is_prime(i):
        sum_of_primes += i

print(f"ผลรวมของจำนวนเฉพาะที่น้อยกว่า 10000 คือ: {sum_of_primes}")

